create extension if not exists pgcrypto;
create schema auth;
create role anon nologin;
create role authenticated nologin;
create table auth.users(id uuid primary key,email text,is_anonymous boolean not null default false,raw_app_meta_data jsonb not null default '{}');
create function auth.uid() returns uuid language sql stable as $$ select (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid $$;
create function auth.jwt() returns jsonb language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb,'{}'::jsonb) $$;
grant usage on schema public,auth to anon,authenticated;
grant execute on function auth.uid(),auth.jwt() to anon,authenticated;
create table public.workspaces(id uuid primary key default gen_random_uuid(),name text not null,image_url text,created_by uuid references auth.users,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users,display_name text,avatar_url text,email text);
create table public.workspace_members(workspace_id uuid references public.workspaces on delete cascade,user_id uuid references auth.users on delete cascade,role text not null default 'member' check(role in ('admin','member')),joined_at timestamptz not null default now(),primary key(workspace_id,user_id));
create table public.workspace_invites(token text primary key default encode(gen_random_bytes(16),'hex'),workspace_id uuid not null references public.workspaces on delete cascade,created_by uuid references auth.users,expires_at timestamptz not null default now()+interval '7 days',created_at timestamptz not null default now());
create table public.transactions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces,amount numeric(15,2) not null);
create table public.app_configs(key text primary key,value text not null,description text,updated_at timestamptz default now());
create function public.is_workspace_member(ws_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.workspace_members where workspace_id=ws_id and user_id=auth.uid()) $$;
create function public.user_workspace_ids(uid uuid) returns setof uuid language sql stable security definer set search_path=public as $$ select workspace_id from public.workspace_members where user_id=uid $$;
create function public.user_admin_workspace_ids(uid uuid) returns setof uuid language sql stable security definer set search_path=public as $$ select workspace_id from public.workspace_members where user_id=uid and role='admin' $$;
alter table public.workspaces enable row level security;
alter table public.workspace_members enable row level security;
alter table public.workspace_invites enable row level security;
alter table public.transactions enable row level security;
alter table public.app_configs enable row level security;
create policy ws_select on public.workspaces for select using(created_by=auth.uid() or public.is_workspace_member(id) or exists(select 1 from public.workspace_invites where workspace_id=workspaces.id and expires_at>now()));
create policy ws_insert on public.workspaces for insert with check(created_by=auth.uid());
create policy ws_update on public.workspaces for update using(created_by=auth.uid());
create policy ws_delete on public.workspaces for delete using(created_by=auth.uid());
create policy wm_select on public.workspace_members for select using(workspace_id in(select public.user_workspace_ids(auth.uid())));
create policy wm_insert on public.workspace_members for insert with check(auth.uid() is not null);
create policy wm_delete on public.workspace_members for delete using(user_id=auth.uid() or workspace_id in(select public.user_admin_workspace_ids(auth.uid())));
create policy "Baca invite valid" on public.workspace_invites for select using(expires_at>now());
create policy "Admin buat invite" on public.workspace_invites for insert with check(public.is_workspace_member(workspace_id));
create policy tx_all on public.transactions for all using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy configs_read on public.app_configs for select using(true);
grant select,insert,update,delete on all tables in schema public to authenticated;
grant select on all tables in schema public to anon;
create function public.test_assert(ok boolean,message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'QR_JOIN_ASSERT: %',message; end if; end $$;
